css:
/* the scrim exists in the DOM at every width, so it is hidden here rather
   than only inside the mobile query */
.nav-scrim{display:none}

@media (max-width:1100px){
  /* 1. free the fixed panel from the header's containing block */
  .hdr{-webkit-backdrop-filter:none;backdrop-filter:none}

  /* 2. shut is shut */
  .nav{display:none}
  .navtog:checked ~ .nav{
    display:block;position:fixed;left:0;right:0;
    top:var(--nav-top,var(--hdr-h));bottom:0;height:auto;
    opacity:1;visibility:visible;clip-path:none;pointer-events:auto;
    overflow-y:auto;overscroll-behavior:contain;
    background:var(--paper);z-index:68;
    padding:6px var(--gut) 40px}

  /* 3. a scrim to tap, under the panel and over the page */
  .navtog:checked ~ .nav-scrim{
    display:block;position:fixed;left:0;right:0;
    top:var(--nav-top,var(--hdr-h));bottom:0;z-index:67;
    background:rgba(28,27,25,.45);border:0;padding:0;margin:0;
    -webkit-appearance:none;appearance:none}

  /* the page behind must not scroll while the menu is open */
  body.nav-open{overflow:hidden}

  /* a compact header row: the logo no longer eats half the screen */
  .brand img{height:50px}
  .hdr-in{min-height:66px;gap:12px}
  .hdr-act{gap:10px}

  /* one utility line, not two: the tagline is decoration, the number is not */
  .util-tag{display:none}
  .util-in{min-height:40px;justify-content:center;gap:14px}
  .util-r{gap:14px}

  /* while the menu is open the floating controls are clutter: the menu
     already carries both calls to action */
  body.nav-open .sticky-bar,
  body.nav-open .side-quote,
  body.nav-open .totop{display:none}

  /* room to breathe in the open menu, and a clear end to it */
  .navtog:checked ~ .nav .nav-list > li:first-child{border-top:1px solid var(--line)}
  .navtog:checked ~ .nav .nav-cta{margin-top:20px}
}
@media (max-width:1100px) and (prefers-reduced-motion:no-preference){
  .navtog:checked ~ .nav{animation:navIn .18s ease-out both}
  @keyframes navIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
}
